"use strict";

const fs = require("node:fs");
const path = require("node:path");

// Mimics the parts of the Rollup bundle API the observer reads: chunks carry
// per-module renderedLength, plugins' outputOptions hooks can replace the
// output options, write stores exactly the returned code or source, and
// generateBundle and writeBundle hooks run before and after the files are
// written.
function render(chunks) {
  return {
    output: [
      ...chunks.map((chunk) => ({ type: "chunk", fileName: chunk.fileName, code: chunk.code, modules: chunk.modules })),
      { type: "asset", fileName: "style.css", source: "body{}" },
    ],
  };
}

async function rollup(inputOptions) {
  return {
    cache: undefined,
    async generate() {
      return render(inputOptions.chunks);
    },
    async write(rawOutputOptions) {
      let outputOptions = rawOutputOptions;
      for (const plugin of inputOptions.plugins || []) {
        if (plugin.outputOptions) outputOptions = plugin.outputOptions(outputOptions) || outputOptions;
      }
      const result = render(inputOptions.chunks);
      for (const plugin of inputOptions.plugins || []) {
        if (plugin.generateBundle) await plugin.generateBundle(outputOptions, result);
      }
      const dir = outputOptions.dir ? path.resolve(outputOptions.dir) : path.dirname(path.resolve(outputOptions.file));
      fs.mkdirSync(dir, { recursive: true });
      for (const item of result.output) {
        fs.writeFileSync(path.join(dir, item.fileName), item.type === "chunk" ? item.code : item.source);
      }
      for (const plugin of inputOptions.plugins || []) {
        if (plugin.writeBundle) await plugin.writeBundle(outputOptions, result);
      }
      return result;
    },
    async close() {},
  };
}

module.exports = { rollup, VERSION: "4.65.0" };
